import type { components } from "@/lib/api/schema";

type MissionState = components["schemas"]["MissionState"];

export type StorageErrorCode = "unavailable" | "quota" | "not-found" | "corrupt";

export interface StorageError {
  code: StorageErrorCode;
  message: string;
}

export type StorageResult<T> =
  | { ok: true; value: T }
  | { ok: false; error: StorageError };

export const MISSION_KEY_PREFIX = "missionforge:mission:";

/** IDs are generated by the backend (`mission-<hex>`); reject anything else before touching storage. */
const MISSION_ID_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;

export function isValidMissionId(id: string): boolean {
  return MISSION_ID_PATTERN.test(id);
}

const fail = (code: StorageErrorCode, message: string): { ok: false; error: StorageError } => ({
  ok: false,
  error: { code, message },
});

function isQuotaError(cause: unknown): boolean {
  return (
    cause instanceof DOMException &&
    (cause.name === "QuotaExceededError" || cause.name === "NS_ERROR_DOM_QUOTA_REACHED")
  );
}

function getStorage(): Storage | null {
  try {
    return typeof window === "undefined" ? null : window.localStorage;
  } catch {
    return null;
  }
}

const isObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

function looksLikeMission(value: unknown): value is MissionState {
  if (!isObject(value)) return false;
  const m = value;
  return (
    m.schemaVersion === "1.0" &&
    typeof m.missionId === "string" &&
    isValidMissionId(m.missionId) &&
    typeof m.designRevision === "number" &&
    Number.isInteger(m.designRevision) &&
    m.designRevision >= 0 &&
    typeof m.scenarioId === "string" &&
    typeof m.title === "string" &&
    isObject(m.architecture) &&
    Array.isArray(m.architecture.instrumentIds) &&
    m.architecture.instrumentIds.every((id) => typeof id === "string") &&
    Array.isArray(m.scienceObjectives) &&
    isObject(m.operations) &&
    isObject(m.constraints)
  );
}

export function saveMission(state: MissionState): StorageResult<void> {
  if (!isValidMissionId(state.missionId)) {
    return fail("corrupt", "Mission id is not valid.");
  }
  const storage = getStorage();
  if (!storage) return fail("unavailable", "Browser storage is unavailable.");
  try {
    storage.setItem(MISSION_KEY_PREFIX + state.missionId, JSON.stringify(state));
    return { ok: true, value: undefined };
  } catch (cause) {
    return isQuotaError(cause)
      ? fail("quota", "Browser storage is full.")
      : fail("unavailable", "Browser storage could not be written.");
  }
}

export function loadMission(missionId: string): StorageResult<MissionState> {
  if (!isValidMissionId(missionId)) return fail("not-found", "Mission id is not valid.");
  const storage = getStorage();
  if (!storage) return fail("unavailable", "Browser storage is unavailable.");
  let raw: string | null;
  try {
    raw = storage.getItem(MISSION_KEY_PREFIX + missionId);
  } catch {
    return fail("unavailable", "Browser storage could not be read.");
  }
  if (raw === null) return fail("not-found", "No saved mission with this id.");
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!looksLikeMission(parsed) || parsed.missionId !== missionId) {
      return fail("corrupt", "The saved mission could not be read.");
    }
    return { ok: true, value: parsed };
  } catch {
    return fail("corrupt", "The saved mission could not be read.");
  }
}

export interface MissionSummary {
  missionId: string;
  title: string;
  scenarioId: MissionState["scenarioId"];
  designRevision: number;
}

/** Lists readable saved missions; unreadable entries are skipped. */
export function listMissions(): StorageResult<MissionSummary[]> {
  const storage = getStorage();
  if (!storage) return fail("unavailable", "Browser storage is unavailable.");
  const out: MissionSummary[] = [];
  try {
    for (let i = 0; i < storage.length; i += 1) {
      const key = storage.key(i);
      if (!key || !key.startsWith(MISSION_KEY_PREFIX)) continue;
      const loaded = loadMission(key.slice(MISSION_KEY_PREFIX.length));
      if (loaded.ok) {
        const { missionId, title, scenarioId, designRevision } = loaded.value;
        out.push({ missionId, title, scenarioId, designRevision });
      }
    }
  } catch {
    return fail("unavailable", "Browser storage could not be read.");
  }
  out.sort((a, b) => a.missionId.localeCompare(b.missionId));
  return { ok: true, value: out };
}
